      <input type="hidden" name="rangeThrough" value="${dueRange.through}">`;
  const filterInputs = `<input type="hidden" name="filter" value="${filter}">
      <input type="hidden" name="priorityFilter" value="${priorityFilter}">
      ${rangeInputs}`;
